UPDATE classroom_sessions
SET state = #{state}, paused = #{paused}, summary = #{summary}, updated_at = CURRENT_TIMESTAMP
WHERE id = #{id} AND user_id = #{userId}

UPDATE classroom_sessions
SET runtime_index = #{index}, runtime_revision = runtime_revision + 1, runtime_response = #{response}
WHERE id = #{id} AND user_id = #{userId} AND runtime_revision = #{revision}
